//! Gate-for-gate parity against `build_observations`' rejection cascade.
//!
//! The fixture is generated by `scripts/capture_cascade_fixture.py`, which
//! drives the reference itself and reads the decisions back out of the
//! `ObservationBatch` -- rather than reimplementing the gate sequence, which
//! would let the fixture and the port share a misreading and agree with each
//! other while both disagreed with Python.
//!
//! Each rejection carries the GATE that produced it, not just the reason,
//! because reasons are not unique to a gate: gate 3 and gate 6 both report
//! `dropout`, and gates 5 and 6 can both report `vegetation_occlusion`. On
//! reasons alone, a port that ran those gates in the wrong order would pass.

use argusnet_sensing::cascade::{
    evaluate_pair, Blocker, DominantLoss, FovInput, GenerationTally, Outcome, PairInput,
    RejectReason, Visibility,
};
use serde::Deserialize;

#[derive(Deserialize)]
struct Fixture {
    reason_aliasing: Aliasing,
    cases: Vec<Case>,
}

#[derive(Deserialize)]
struct Aliasing {
    object_occlusion_is_building_occlusion: bool,
    distinct_reason_strings: Vec<String>,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    expected: Expected,
}

#[derive(Deserialize)]
struct Expected {
    attempted: u64,
    accepted: u64,
    rejection_counts: std::collections::BTreeMap<String, u64>,
    rejections: Vec<Rejection>,
}

#[derive(Deserialize)]
struct Rejection {
    reason: String,
    gate: String,
}

fn load() -> Fixture {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/fixtures/cascade_decisions.json"
    );
    let text = std::fs::read_to_string(path).expect("fixture readable");
    serde_json::from_str(&text).expect("fixture parses")
}

/// Every reason the fixture recorded must be one this port can produce, and
/// the gate it came from must be one this port routes to that reason.
#[test]
fn every_recorded_reason_and_gate_is_one_the_port_produces() {
    for case in load().cases {
        for rejection in &case.expected.rejections {
            let known = [
                RejectReason::OutOfRange,
                RejectReason::OutsideFov,
                RejectReason::Dropout,
                RejectReason::LowElevation,
                RejectReason::TerrainOcclusion,
                RejectReason::BuildingOcclusion,
                RejectReason::WallOcclusion,
                RejectReason::VegetationOcclusion,
                RejectReason::OutOfCoverage,
            ];
            assert!(
                known.iter().any(|r| r.as_str() == rejection.reason),
                "{}: reason {:?} has no variant in the port",
                case.name,
                rejection.reason
            );
            let expected_reason = match rejection.gate.as_str() {
                "1_range" => "out_of_range",
                "2_fov" => "outside_fov",
                "3_dropout" => "dropout",
                "4_elevation" => "low_elevation",
                // Gate 5 reports whichever blocker the query named; gate 6
                // reports dropout or vegetation_occlusion. Checked below by
                // replaying the gate rather than by a fixed string.
                "5_line_of_sight" | "6_detection" => continue,
                other => panic!("{}: unrecognised gate {other:?}", case.name),
            };
            assert_eq!(
                rejection.reason, expected_reason,
                "{}: gate {} produced reason {:?}",
                case.name, rejection.gate, rejection.reason
            );
        }
    }
}

/// The aliasing that would be easy to "fix" into a behaviour change: Python
/// defines `REJECT_OBJECT_OCCLUSION = REJECT_BUILDING_OCCLUSION`, so ten
/// constants collapse to nine wire strings. If a future port gives the unknown
/// blocker its own string, every rejection count containing one shifts.
#[test]
fn an_unknown_blocker_is_counted_as_a_building_occlusion() {
    let fixture = load();
    assert!(
        fixture
            .reason_aliasing
            .object_occlusion_is_building_occlusion,
        "the reference no longer aliases object onto building occlusion; \
         the port's Blocker::Other mapping needs revisiting"
    );
    assert_eq!(
        fixture.reason_aliasing.distinct_reason_strings.len(),
        9,
        "the reference's set of distinct reason strings changed"
    );

    let base = PairInput {
        range_m: 100.0,
        max_range_m: 1000.0,
        fov: None,
        dropout_probability: 0.0,
        elevation_deg: 45.0,
        required_elevation_deg: 0.5,
        visibility: Visibility::Blocked(Blocker::Other),
        combined_pd: 1.0,
        dominant_loss: DominantLoss::Other,
    };
    let mut draws = || 0.5;
    assert_eq!(
        evaluate_pair(&base, &mut draws),
        Outcome::Rejected(RejectReason::BuildingOcclusion)
    );
    let building = PairInput {
        visibility: Visibility::Blocked(Blocker::Building),
        ..base
    };
    assert_eq!(
        evaluate_pair(&building, &mut draws),
        Outcome::Rejected(RejectReason::BuildingOcclusion)
    );
}

/// The ordering the fixture proves from the reference: identical geometry
/// rejects as `dropout` with dropout enabled and as `low_elevation` with it
/// disabled, so gate 3 really does run before gate 4.
#[test]
fn the_dropout_gate_runs_before_the_elevation_gate() {
    let fixture = load();
    let with_dropout = fixture
        .cases
        .iter()
        .find(|c| c.name == "dropout_precedes_elevation")
        .expect("ordering case present");
    let without = fixture
        .cases
        .iter()
        .find(|c| c.name == "elevation_gate_alone")
        .expect("companion case present");
    assert_eq!(
        with_dropout.expected.rejections[0].gate, "3_dropout",
        "the reference stopped rejecting at the dropout gate"
    );
    assert_eq!(
        without.expected.rejections[0].gate, "4_elevation",
        "the companion case no longer reaches the elevation gate"
    );

    // The port must agree: same input, dropout certain versus disabled.
    let failing_elevation = PairInput {
        range_m: 3000.0,
        max_range_m: 5000.0,
        fov: None,
        dropout_probability: 1.0,
        elevation_deg: -0.02,
        required_elevation_deg: 0.5,
        visibility: Visibility::Visible,
        combined_pd: 1.0,
        dominant_loss: DominantLoss::Other,
    };
    let mut draws = || 0.5;
    assert_eq!(
        evaluate_pair(&failing_elevation, &mut draws),
        Outcome::Rejected(RejectReason::Dropout),
        "a pair that would fail elevation must still be caught by dropout first"
    );
    let no_dropout = PairInput {
        dropout_probability: 0.0,
        ..failing_elevation
    };
    assert_eq!(
        evaluate_pair(&no_dropout, &mut draws),
        Outcome::Rejected(RejectReason::LowElevation)
    );
}

/// Gate 3 consumes its draw even when a later gate would have rejected the
/// pair. That is what makes the shared-stream path order-dependent, and it is
/// the property a "tidy up the gate order" change would silently break.
#[test]
fn the_dropout_draw_is_consumed_even_when_a_later_gate_would_reject() {
    let doomed = PairInput {
        range_m: 100.0,
        max_range_m: 1000.0,
        fov: None,
        dropout_probability: 0.0,
        elevation_deg: -10.0,
        required_elevation_deg: 0.5,
        visibility: Visibility::Visible,
        combined_pd: 1.0,
        dominant_loss: DominantLoss::Other,
    };
    let mut count = 0;
    let mut draws = || {
        count += 1;
        0.9
    };
    assert_eq!(
        evaluate_pair(&doomed, &mut draws),
        Outcome::Rejected(RejectReason::LowElevation)
    );
    assert_eq!(
        count, 1,
        "the elevation rejection must still have cost one dropout draw"
    );

    // A gate-1 or gate-2 rejection, by contrast, draws nothing at all.
    let out_of_range = PairInput {
        range_m: 5000.0,
        ..doomed
    };
    let mut count = 0;
    let mut draws = || {
        count += 1;
        0.9
    };
    assert_eq!(
        evaluate_pair(&out_of_range, &mut draws),
        Outcome::Rejected(RejectReason::OutOfRange)
    );
    assert_eq!(count, 0, "gates 1 and 2 must be draw-free");
}

/// Gate 6 reports two different reasons from one gate, depending on which loss
/// dominated -- and one of them collides with gate 3's.
#[test]
fn the_detection_gate_reports_by_dominant_loss() {
    let base = PairInput {
        range_m: 100.0,
        max_range_m: 1000.0,
        fov: None,
        dropout_probability: 0.0,
        elevation_deg: 45.0,
        required_elevation_deg: 0.5,
        visibility: Visibility::Visible,
        combined_pd: 0.1,
        dominant_loss: DominantLoss::Other,
    };
    let mut draws = || 0.9;
    assert_eq!(
        evaluate_pair(&base, &mut draws),
        Outcome::Rejected(RejectReason::Dropout),
        "a range-dominated detection failure reports dropout, like gate 3"
    );
    let vegetation = PairInput {
        dominant_loss: DominantLoss::Transmittance,
        ..base
    };
    assert_eq!(
        evaluate_pair(&vegetation, &mut draws),
        Outcome::Rejected(RejectReason::VegetationOcclusion)
    );
}

/// The gate is `draw > p_d`, and the asymmetry that follows is worth pinning
/// rather than smoothing over.
///
/// `p_d = 1` accepts for every draw, because `random()` returns [0, 1) and so
/// can never exceed one. But `p_d = 0` does **not** reject for every draw: a
/// draw of exactly `0.0` gives `0.0 > 0.0`, which is false, so an impossible
/// detection is accepted. numpy's `random()` can return exactly zero, so this
/// is reachable rather than merely theoretical -- about once in 2^53 draws.
///
/// My first version of this test asserted the tidy symmetric behaviour and
/// failed against the port. The port was right; a `>=` here would have been a
/// silent behaviour change at the boundary.
#[test]
fn detection_boundaries_are_asymmetric_at_certainty() {
    let make = |pd: f64| PairInput {
        range_m: 100.0,
        max_range_m: 1000.0,
        fov: None,
        dropout_probability: 0.0,
        elevation_deg: 45.0,
        required_elevation_deg: 0.5,
        visibility: Visibility::Visible,
        combined_pd: pd,
        dominant_loss: DominantLoss::Other,
    };
    // Certainty accepts at every attainable draw.
    for draw in [0.0, 0.5, 0.999_999] {
        let mut d = || draw;
        assert_eq!(
            evaluate_pair(&make(1.0), &mut d),
            Outcome::Accepted { fov_fraction: 0.0 },
            "p_d = 1 must accept at draw {draw}"
        );
    }
    // Impossibility rejects at every draw ABOVE zero.
    for draw in [f64::MIN_POSITIVE, 0.5, 0.999_999] {
        let mut d = || draw;
        assert_eq!(
            evaluate_pair(&make(0.0), &mut d),
            Outcome::Rejected(RejectReason::Dropout),
            "p_d = 0 must reject at draw {draw}"
        );
    }
    // ...and accepts at exactly zero, which is the asymmetry.
    let mut d = || 0.0;
    assert_eq!(
        evaluate_pair(&make(0.0), &mut d),
        Outcome::Accepted { fov_fraction: 0.0 },
        "draw of exactly 0.0 accepts even at p_d = 0, because the gate is `>`"
    );
}

/// The FOV gate is skipped, not failed, when no look direction resolves -- the
/// reference's behaviour for a static directional node, which the fixture's
/// `directional_sensor_without_look_direction` case records.
#[test]
fn a_directional_sensor_without_a_look_direction_skips_the_gate() {
    let fixture = load();
    let case = fixture
        .cases
        .iter()
        .find(|c| c.name == "directional_sensor_without_look_direction")
        .expect("case present");
    assert!(
        !case.expected.rejections.iter().any(|r| r.gate == "2_fov"),
        "the reference began rejecting at the FOV gate without a look direction"
    );

    let no_fov = PairInput {
        range_m: 100.0,
        max_range_m: 1000.0,
        fov: None,
        dropout_probability: 0.0,
        elevation_deg: 45.0,
        required_elevation_deg: 0.5,
        visibility: Visibility::Visible,
        combined_pd: 1.0,
        dominant_loss: DominantLoss::Other,
    };
    let mut draws = || 0.5;
    assert_eq!(
        evaluate_pair(&no_fov, &mut draws),
        Outcome::Accepted { fov_fraction: 0.0 }
    );
}

/// The FOV fraction floors its divisor at one degree, so a very narrow sensor
/// cannot report a fraction far above one.
#[test]
fn the_fov_fraction_floors_its_divisor() {
    let narrow = PairInput {
        range_m: 100.0,
        max_range_m: 1000.0,
        fov: Some(FovInput {
            angle_deg: 0.4,
            half_angle_deg: 0.5,
        }),
        dropout_probability: 0.0,
        elevation_deg: 45.0,
        required_elevation_deg: 0.5,
        visibility: Visibility::Visible,
        combined_pd: 1.0,
        dominant_loss: DominantLoss::Other,
    };
    let mut draws = || 0.5;
    match evaluate_pair(&narrow, &mut draws) {
        Outcome::Accepted { fov_fraction } => assert!(
            (fov_fraction - 0.4).abs() < 1e-12,
            "divisor must floor at 1 degree, giving 0.4/1.0, got {fov_fraction}"
        ),
        other => panic!("expected acceptance, got {other:?}"),
    }
}

/// The tally must account for every pair: accepted plus rejected equals
/// attempted, and the reference's own totals must match.
#[test]
fn the_tally_accounts_for_every_pair() {
    for case in load().cases {
        let mut tally = GenerationTally::default();
        for rejection in &case.expected.rejections {
            let reason = [
                RejectReason::OutOfRange,
                RejectReason::OutsideFov,
                RejectReason::Dropout,
                RejectReason::LowElevation,
                RejectReason::TerrainOcclusion,
                RejectReason::BuildingOcclusion,
                RejectReason::WallOcclusion,
                RejectReason::VegetationOcclusion,
                RejectReason::OutOfCoverage,
            ]
            .into_iter()
            .find(|r| r.as_str() == rejection.reason)
            .expect("known reason");
            tally.record("n", "t", Outcome::Rejected(reason));
        }
        for _ in 0..case.expected.accepted {
            tally.record("n", "t", Outcome::Accepted { fov_fraction: 0.0 });
        }
        assert_eq!(
            tally.attempted, case.expected.attempted,
            "{}: attempted count",
            case.name
        );
        assert_eq!(
            tally.accepted + tally.rejected(),
            tally.attempted,
            "{}: accepted + rejected must equal attempted",
            case.name
        );
        let counts: std::collections::BTreeMap<String, u64> = tally
            .rejection_counts
            .iter()
            .map(|(k, v)| ((*k).to_string(), *v))
            .collect();
        assert_eq!(
            counts, case.expected.rejection_counts,
            "{}: rejection counts by reason",
            case.name
        );
    }
}

/// Gate 1 has a lower bound as well as an upper one: a target coincident with
/// the node has a line of sight with no direction, so the reference rejects it
/// as out of range rather than dividing by a near-zero length. The fixture's
/// `range_gate_both_bounds` case records both, and this replays the lower one
/// through the port -- without it, deleting the bound changed nothing.
#[test]
fn a_target_coincident_with_the_node_is_out_of_range() {
    let make = |range_m: f64| PairInput {
        range_m,
        max_range_m: 1000.0,
        fov: None,
        dropout_probability: 0.0,
        elevation_deg: 45.0,
        required_elevation_deg: 0.5,
        visibility: Visibility::Visible,
        combined_pd: 1.0,
        dominant_loss: DominantLoss::Other,
    };
    for range_m in [0.0, 1e-9, 9.9e-7] {
        let mut draws = || 0.5;
        assert_eq!(
            evaluate_pair(&make(range_m), &mut draws),
            Outcome::Rejected(RejectReason::OutOfRange),
            "range {range_m} is below the 1e-6 floor and must be rejected"
        );
    }
    // Just above the floor the pair survives gate 1.
    let mut draws = || 0.5;
    assert_eq!(
        evaluate_pair(&make(1.1e-6), &mut draws),
        Outcome::Accepted { fov_fraction: 0.0 }
    );

    // And the fixture confirms the reference rejects both bounds the same way.
    let fixture = load();
    let case = fixture
        .cases
        .iter()
        .find(|c| c.name == "range_gate_both_bounds")
        .expect("case present");
    assert_eq!(case.expected.rejection_counts.get("out_of_range"), Some(&2));
}

/// The FOV gate is `angle > half_angle`, so a target sitting exactly on the
/// cone boundary is inside it. That also makes the fraction exactly one, which
/// is the maximum edge-degradation the accepted path applies.
#[test]
fn a_target_exactly_on_the_fov_boundary_is_inside_it() {
    let on_boundary = PairInput {
        range_m: 100.0,
        max_range_m: 1000.0,
        fov: Some(FovInput {
            angle_deg: 30.0,
            half_angle_deg: 30.0,
        }),
        dropout_probability: 0.0,
        elevation_deg: 45.0,
        required_elevation_deg: 0.5,
        visibility: Visibility::Visible,
        combined_pd: 1.0,
        dominant_loss: DominantLoss::Other,
    };
    let mut draws = || 0.5;
    match evaluate_pair(&on_boundary, &mut draws) {
        Outcome::Accepted { fov_fraction } => assert!(
            (fov_fraction - 1.0).abs() < 1e-12,
            "a target on the boundary sits at fraction 1.0, got {fov_fraction}"
        ),
        other => panic!("boundary must be inside the cone, got {other:?}"),
    }

    // A hair outside it is rejected.
    let outside = PairInput {
        fov: Some(FovInput {
            angle_deg: 30.000_001,
            half_angle_deg: 30.0,
        }),
        ..on_boundary
    };
    let mut draws = || 0.5;
    assert_eq!(
        evaluate_pair(&outside, &mut draws),
        Outcome::Rejected(RejectReason::OutsideFov)
    );
}

/// The elevation gate is `elevation < required`, so a target sitting exactly
/// at the floor passes. Every gate boundary in this cascade is exclusive on
/// the rejecting side; pinning each one separately, because a single `<=`
/// slipped in anywhere changes which pairs survive.
#[test]
fn a_target_exactly_at_the_elevation_floor_passes() {
    let make = |elevation_deg: f64| PairInput {
        range_m: 100.0,
        max_range_m: 1000.0,
        fov: None,
        dropout_probability: 0.0,
        elevation_deg,
        required_elevation_deg: 0.5,
        visibility: Visibility::Visible,
        combined_pd: 1.0,
        dominant_loss: DominantLoss::Other,
    };
    let mut draws = || 0.5;
    assert_eq!(
        evaluate_pair(&make(0.5), &mut draws),
        Outcome::Accepted { fov_fraction: 0.0 },
        "exactly at the floor is not below it"
    );
    let mut draws = || 0.5;
    assert_eq!(
        evaluate_pair(&make(0.499_999), &mut draws),
        Outcome::Rejected(RejectReason::LowElevation)
    );
}
